public enum DrawOp {
    
    case fillPath(path: PathData, paint: Paint, rule: FillRule, opacity: Float, transform: Affine
    )
    case strokePath(path: PathData, paint: Paint, params: StrokeParams, opacity: Float, transform: Affine
    )
