    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DrawOp {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .fillPath(path: try FfiConverterTypePathData.read(from: &buf), paint: try FfiConverterTypePaint.read(from: &buf), rule: try FfiConverterTypeFillRule.read(from: &buf), opacity: try FfiConverterFloat.read(from: &buf), transform: try FfiConverterTypeAffine.read(from: &buf)
