        )
        
        case 3: return .pushClip(path: try FfiConverterTypePathData.read(from: &buf), rule: try FfiConverterTypeFillRule.read(from: &buf), transform: try FfiConverterTypeAffine.read(from: &buf)
        )
        
        case 4: return .popClip
        
        case 5: return .pushLayer(opacity: try FfiConverterFloat.read(from: &buf)
        )
        
        case 6: return .popLayer
        
        case 7: return .image(data: try FfiConverterData.read(from: &buf), format: try FfiConverterTypeImageFormat.read(from: &buf), x: try FfiConverterFloat.read(from: &buf), y: try FfiConverterFloat.read(from: &buf), width: try FfiConverterFloat.read(from: &buf), height: try FfiConverterFloat.read(from: &buf), transform: try FfiConverterTypeAffine.read(from: &buf)
