            FfiConverterTypePaint.write(paint, into: &buf)
            FfiConverterTypeStrokeParams.write(params, into: &buf)
            FfiConverterFloat.write(opacity, into: &buf)
            FfiConverterTypeAffine.write(transform, into: &buf)
            
        
